/* HEXA BATTLEGROUNDS setup — PART 6 OF 19. Run parts in order. Safe to re-run. */ create or replace function host_import_teams(p_token text, p_teams jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; r jsonb; v_salt text; v_arena uuid; v_size int; v_n int := 0; v_team uuid; begin v_ev := _auth_host(p_token); v_size := _cfg(v_ev, 'arena_size'); for r in select * from jsonb_array_elements(p_teams) loop if (r ->> 'number') is null or (r ->> 'pin') is null or length(r ->> 'pin') < 4 then raise exception 'BAD_ROW'; end if; v_arena := null; if (r ->> 'map') is not null then select id into v_arena from arenas where event_id = v_ev and number = (r ->> 'map')::int; end if; if v_arena is null then select a.id into v_arena from arenas a where a.event_id = v_ev and a.phase = 'lobby' and (select count(*) from teams t where t.arena_id = a.id) < v_size order by a.number limit 1; end if; if v_arena is null then raise exception 'ALL_MAPS_FULL'; end if; v_salt := _new_token(); insert into teams(event_id, arena_id, number, name, pin_salt, pin_hash) values (v_ev, v_arena, (r ->> 'number')::int, coalesce(nullif(r ->> 'name', ''), 'Squad ' || (r ->> 'number')), v_salt, _hash(v_salt || (r ->> 'pin'))) on conflict (event_id, number) do update set name = excluded.name, pin_salt = excluded.pin_salt, pin_hash = excluded.pin_hash, arena_id = case when (select phase from arenas where id = teams.arena_id) = 'lobby' then excluded.arena_id else teams.arena_id end returning id into v_team; if not exists (select 1 from inventory where team_id = v_team) then perform _add_item(v_team, 'pistol', 1); perform _add_item(v_team, 'medkit', 1); end if; v_n := v_n + 1; end loop; insert into audit_log(event_id, actor, action, args) values (v_ev, 'host', 'import_teams', jsonb_build_object('count', v_n)); return jsonb_build_object('imported', v_n); end $$; create or replace function host_overview(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; e events; r record; begin v_ev := _auth_host(p_token); for r in select id from arenas where event_id = v_ev loop perform _tick(r.id); end loop; select * into e from events where id = v_ev; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('id', e.id, 'code', e.code, 'name', e.name, 'settings', _defaults() || e.settings, 'grand_revealed', e.grand_revealed, 'seed', e.mission_seed), 'arenas', (select coalesce(jsonb_agg(to_jsonb(a) - 'last_tick_at' order by a.number), '[]'::jsonb) from arenas a where a.event_id = v_ev), 'teams', (select coalesce(jsonb_agg(jsonb_build_object( 'id', t.id, 'number', t.number, 'name', t.name, 'arena_id', t.arena_id, 'ready', t.ready, 'roster_locked', t.roster_locked, 'bus', t.bus, 'hp', t.hp, 'shield', t.shield, 'coins', t.coins, 'points', t.points, 'trust', t.trust, 'final_points', t.final_points, 'missions', t.missions_completed, 'battles', t.battle_wins, 'location', t.location_id, 'state', t.state, 'travel_to', t.travel_to, 'jammed', t.jammed_until > now(), 'protected', t.protected_until > now(), 'players', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.display_name, 'role', p.role, 'online', p.last_seen_at > now() - interval '25 seconds') order by p.joined_at), '[]'::jsonb) from players p where p.team_id = t.id and p.active), 'inventory', (select coalesce(jsonb_object_agg(item_id, qty), '{}'::jsonb) from inventory where team_id = t.id and qty > 0), 'activity', (select jsonb_build_object('id', mi.id, 'kind', mi.kind, 'title', mt.title, 'template', mt.id, 'attempts_left', mi.attempts_left, 'deadline', mi.deadline, 'hint_used', mi.hint_used, 'answer', mt.parts, 'relay_key', mi.relay_key, 'explanation', mt.explanation) from mission_instances mi join mission_templates mt on mt.id = mi.template_id where mi.team_id = t.id and mi.status = 'active' order by (mi.kind = 'battle') desc, mi.created_at desc limit 1) ) order by t.number), '[]'::jsonb) from teams t where t.event_id = v_ev), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'arena_id', b.arena_id, 'weapon', b.weapon, 'attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'deadline', b.deadline)), '[]'::jsonb) from battles b join arenas a on a.id = b.arena_id where a.event_id = v_ev and b.status = 'active'), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'arena_id', d.arena_id, 'location', d.location_id, 'tier', d.tier, 'status', d.status, 'expires_at', d.expires_at)), '[]'::jsonb) from airdrops d join arenas a on a.id = d.arena_id where a.event_id = v_ev and d.status = 'open'), 'sync_rounds', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'arena_id', s.arena_id, 'stage', s.stage, 'kind', s.kind, 'deadline', s.deadline, 'status', s.status, 'solved', (select count(*) from mission_instances where sync_round_id = s.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = s.id))), '[]'::jsonb) from sync_rounds s join arenas a on a.id = s.arena_id where a.event_id = v_ev and s.started_at > now() - interval '30 minutes'), 'reports', (select count(*) from chat_messages c join arenas a on a.id = c.arena_id where a.event_id = v_ev and c.reported and not c.hidden), 'metrics', jsonb_build_object( 'players_online', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active and p.last_seen_at > now() - interval '25 seconds'), 'players_total', (select count(*) from players p join teams t on t.id = p.team_id where t.event_id = v_ev and p.active), 'squads_ready', (select count(*) from teams where event_id = v_ev and ready), 'submissions_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and s.at > now() - interval '5 minutes'), 'wrong_5m', (select count(*) from submissions s join teams t on t.id = s.team_id where t.event_id = v_ev and not s.correct and s.at > now() - interval '5 minutes'), 'missions_solved', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status = 'solved'), 'missions_failed', (select count(*) from mission_instances mi join teams t on t.id = mi.team_id where t.event_id = v_ev and mi.status in ('failed', 'expired')), 'host_errors', (select count(*) from audit_log where event_id = v_ev and not ok and action <> 'login_failed')), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('arena_id', f.arena_id, 'type', f.type, 'payload', f.payload, 'at', f.at) order by f.id desc), '[]'::jsonb) from (select g.* from game_feed g join arenas a on a.id = g.arena_id where a.event_id = v_ev order by g.id desc limit 40) f) ); end $$; create or replace function host_command(p_token text, p_arena uuid, p_cmd text, p_args jsonb default '{}'::jsonb, p_reason text default null) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_ids uuid[]; v_id uuid; v_out jsonb := '{}'::jsonb; v_err text; v_all_ok text[] := array['open_boarding','assign_buses','drive','finalize_roles','pause','resume','broadcast','clear_overlay', 'blackout','countdown','story','bargain','zone_warn','zone_now','zone_cancel','zone_set','spawn_airdrop','begin_finale', 'finale_stage','launch_sync','close_sync','lock_results','reveal_winner','end_game','reveal_squad00']; begin v_ev := _auth_host(p_token); p_args := coalesce(p_args, '{}'::jsonb); if p_arena is null then if p_cmd = any(v_all_ok) then select array_agg(id order by number) into v_ids from arenas where event_id = v_ev; else v_ids := array[null::uuid]; end if; else if not exists (select 1 from arenas where id = p_arena and event_id = v_ev) then raise exception 'BAD_ARENA'; end if; v_ids := array[p_arena]; end if; foreach v_id in array v_ids loop begin v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), _host_exec(v_ev, v_id, p_cmd, p_args, p_reason)); insert into audit_log(event_id, arena_id, actor, action, args, reason) values (v_ev, v_id, 'host', p_cmd, p_args, p_reason); exception when others then v_err := sqlerrm; insert into audit_log(event_id, arena_id, actor, action, args, reason, ok, error) values (v_ev, v_id, 'host', p_cmd, p_args, p_reason, false, v_err); if array_length(v_ids, 1) = 1 then return jsonb_build_object('ok', false, 'error', v_err); end if; v_out := v_out || jsonb_build_object(coalesce(v_id::text, 'event'), jsonb_build_object('error', v_err)); end; if v_id is not null then perform _ping_arena(v_id, 'host'); end if; end loop; return jsonb_build_object('ok', true, 'result', v_out); end $$;
